function openDailyReconciliation(entry){entry.read=true;saveSessionRecords();openNewConversation();currentSessionId=entry.id;const name=document.getElementById('current-person')?.textContent||'小敏';document.getElementById('messages').innerHTML='<article class="daily-recon"><header>✦ 库存作业智能体</header><p>'+name+'，已完成 2026-10-27 的库存交易对账。MetaERP 与 SCM 合并核对 129 项，其中 126 项一致，发现 <b class="error">3 项不一致</b>。</p><div class="daily-scope">库存组织：华东库存组织　 ·　业务日期：2026-10-27 00:00–23:59　 ·　对账完成：2026-10-28 08:00</div><div class="daily-metrics"><span>MetaERP 库存交易<strong>128 笔</strong></span><span>SCM 库存记录<strong>128 笔</strong></span><span>待核实差异<strong class="error">3 项</strong></span></div><h3>差异明细</h3><div class="daily-table"></div><p class="daily-scope">按库存组织、物料、子库、交易参考匹配，统一单位后比较。正数为入库，负数为出库；单侧缺失也计为一项差异。</p><h3>对账总结</h3><ul><li>数量差异 1 项：主控板转库在 MetaERP 出库 200 块，SCM 记录 180 块，相差 20 块。建议优先核对转库单和 SCM 同步记录。</li><li>SCM 缺失 1 项：MetaERP 已记录连接器入库 120 个，SCM 未找到对应记录。建议检查接收记录及同步日志。</li><li>MetaERP 缺失 1 项：SCM 记录铝制外壳出库 30 套，MetaERP 未找到对应交易。建议核对业务单据与补录情况。</li></ul><p>建议先确认 20 块主控板的数量差异，再排查两项缺失记录。同步延迟、交易参考不一致等是可能原因，需结合原始记录核实。</p><div class="daily-actions"><button data-export>导出 Excel</button><button data-share>分享到 WeLink</button><button data-details>查看对账明细</button></div><div class="daily-detail" hidden><h3>对账明细 · 华东库存组织</h3><p>合并记录 129 项　·　一致 126 项　·　不一致 3 项</p></div></article>';const box=document.querySelector('.daily-recon'),headers=['交易参考','物料 / 子库','MetaERP 交易数量','SCM 记录数量','对账结果'],rows=[['TR-20261027-018','PCB-A100 主控板 · RM01','-200 块','-180 块','数量不一致'],['RCV-20261027-006','CON-D400 连接器 · RM01','+120 个','无记录','SCM 缺少记录'],['MI-20261027-003','HSG-A100 铝制外壳 · WIP01','无记录','-30 套','MetaERP 缺少记录']];const table='<table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((x,i)=>'<td'+(i===4?' class="error"':'')+'>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';box.querySelector('.daily-table').innerHTML=table;box.querySelector('[data-details]').onclick=()=>{const d=box.querySelector('.daily-detail');d.hidden=!d.hidden;if(!d.querySelector('table'))d.insertAdjacentHTML('beforeend',table);d.scrollIntoView({behavior:'smooth',block:'nearest'})};box.querySelector('[data-export]').onclick=()=>{const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.join('\t')).join('\n')],{type:'text/tab-separated-values;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='每日检查库存交易对账.tsv';a.click();URL.revokeObjectURL(a.href)};box.querySelector('[data-share]').onclick=()=>{openWeLinkShare('核查库存交易差异与同步记录')};document.getElementById('title').textContent='每日检查库存交易对账';promptBox.placeholder='例如：哪些记录有差异？应该先核实哪一项？';renderSessionHistory();}
const dailyStyle=document.createElement('style');dailyStyle.textContent='.daily-recon{background:white;padding:22px;border:1px solid #e2e8f0;border-radius:12px;font-size:14px;line-height:1.8;color:#24354b}.daily-recon header{font-weight:700;color:#0067d1}.daily-recon .error{color:#d8454f}.daily-scope{font-size:12px;color:#78879b}.daily-metrics{display:flex;gap:12px;margin:18px 0}.daily-metrics>span{flex:1;padding:14px;background:#f5f7fb;border-radius:8px}.daily-metrics strong{display:block;font-size:22px}.daily-table,.daily-detail{overflow:auto}.daily-recon table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}.daily-recon th,.daily-recon td{border:1px solid #e1e7f0;padding:10px;text-align:left}.daily-recon th{background:#f3f6fa}.daily-actions{display:flex;gap:10px}.daily-actions button{border:1px solid #d8e3f1;border-radius:7px;padding:8px 13px;background:white;color:#0067d1;cursor:pointer}.daily-detail{margin-top:20px}';document.head.append(dailyStyle);
